mapper.select:
select id, user_id, profile_id, profile_version, dimension_key, status,
       correction_value_json, reject_reason, confirmed_by, confirmed_at,
       create_time, update_time
from learner_profile_confirmation
where user_id = #{userId} and profile_id = #{profileId}
  and profile_version = #{profileVersion} and dimension_key = #{dimensionKey}
